import { createServer } from './server.ts';

function parsePort(arg: string | undefined): number {
  const port = Number(arg);
  if (!arg || !Number.isInteger(port) || port < 1 || port > 65535) {
    console.error('usage: app <port>');
    process.exit(2);
  }
  return port;
}

const port = parsePort(process.argv[2]);
const server = createServer();
server.maxConnections = 4096;
server.listen({ port, host: '127.0.0.1', backlog: 1024 }, () => {
  console.error(`kvhttp listening on 127.0.0.1:${port}`);
});

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close();
    server.closeAllConnections();
    process.exit(0);
  });
}

import http, { type IncomingMessage, type ServerResponse } from 'node:http';
import { KvStore } from './store.ts';

export const MAX_VALUE_BYTES = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,64}$/;
const KV_PREFIX = '/kv/';

class HttpError extends Error {
  readonly status: number;
  constructor(status: number, message?: string) {
    super(message ?? http.STATUS_CODES[status] ?? 'Error');
    this.status = status;
  }
}

function send(
  res: ServerResponse,
  status: number,
  body: string | Buffer = '',
  contentType?: string,
): void {
  const payload = typeof body === 'string' ? Buffer.from(body) : body;
  const headers: http.OutgoingHttpHeaders = { 'Content-Length': payload.length };
  if (contentType) headers['Content-Type'] = contentType;
  res.writeHead(status, headers);
  res.end(payload);
}

function allow(res: ServerResponse, methods: readonly string[]): never {
  res.setHeader('Allow', methods.join(', '));
  throw new HttpError(405);
}

async function readBody(req: IncomingMessage, limit: number): Promise<Buffer> {
  const declared = Number(req.headers['content-length'] ?? 0);
  if (declared > limit) throw new HttpError(413);
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req as AsyncIterable<Buffer>) {
    size += chunk.length;
    if (size > limit) throw new HttpError(413);
    chunks.push(chunk);
  }
  return Buffer.concat(chunks, size);
}

async function route(store: KvStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? '';
  const path = req.url ?? '/';

  if (path === '/health') {
    if (method !== 'GET') allow(res, ['GET']);
    return send(res, 200, 'ok', 'text/plain; charset=utf-8');
  }

  if (path === '/kv') {
    if (method !== 'GET') allow(res, ['GET']);
    return send(res, 200, JSON.stringify(store.keys()), 'application/json');
  }

  if (path.startsWith(KV_PREFIX)) {
    const key = path.slice(KV_PREFIX.length);
    if (!KEY_RE.test(key)) throw new HttpError(400, 'invalid key');

    switch (method) {
      case 'GET': {
        const value = store.get(key);
        if (!value) throw new HttpError(404);
        return send(res, 200, value, 'application/octet-stream');
      }
      case 'PUT': {
        const value = await readBody(req, MAX_VALUE_BYTES);
        return send(res, store.put(key, value) ? 201 : 200);
      }
      case 'DELETE':
        if (!store.delete(key)) throw new HttpError(404);
        return send(res, 204);
      default:
        allow(res, ['GET', 'PUT', 'DELETE']);
    }
  }

  throw new HttpError(404);
}

export function createServer(store: KvStore = new KvStore()): http.Server {
  return http.createServer(async (req, res) => {
    try {
      await route(store, req, res);
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      if (res.headersSent) {
        res.destroy();
        return;
      }
      // Don't try to keep reading an oversized or failed body.
      if (!req.complete) res.setHeader('Connection', 'close');
      send(res, status, status === 204 ? '' : `${http.STATUS_CODES[status] ?? 'Error'}\n`, 'text/plain; charset=utf-8');
    }
  });
}

/** In-memory key-value store holding raw byte values. */
export class KvStore {
  readonly #data = new Map<string, Buffer>();

  get(key: string): Buffer | undefined {
    return this.#data.get(key);
  }

  /** Stores the value; returns true if the key was newly created. */
  put(key: string, value: Buffer): boolean {
    const created = !this.#data.has(key);
    this.#data.set(key, value);
    return created;
  }

  delete(key: string): boolean {
    return this.#data.delete(key);
  }

  keys(): string[] {
    return [...this.#data.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  }
}

import { after, before, describe, it } from 'node:test';
import assert from 'node:assert/strict';
import type { AddressInfo } from 'node:net';
import { createServer, MAX_VALUE_BYTES } from '../src/server.ts';

const server = createServer();
let base = '';

before(async () => {
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});
after(() => {
  server.closeAllConnections();
  server.close();
});

const req = (method: string, path: string, body?: Uint8Array<ArrayBuffer> | string) =>
  fetch(base + path, { method, ...(body === undefined ? {} : { body }) });

describe('kvhttp', () => {
  it('health', async () => {
    const res = await req('GET', '/health');
    assert.equal(res.status, 200);
    assert.equal(await res.text(), 'ok');
    assert.equal((await req('POST', '/health')).status, 405);
  });

  it('crud with binary values', async () => {
    const bytes = new Uint8Array([0, 255, 10, 13, 200]);
    assert.equal((await req('PUT', '/kv/bin', bytes)).status, 201);
    assert.equal((await req('PUT', '/kv/bin', bytes)).status, 200);
    const got = await req('GET', '/kv/bin');
    assert.deepEqual(new Uint8Array(await got.arrayBuffer()), bytes);
    assert.equal((await req('DELETE', '/kv/bin')).status, 204);
    assert.equal((await req('DELETE', '/kv/bin')).status, 404);
    assert.equal((await req('GET', '/kv/bin')).status, 404);
  });

  it('empty and max-size values', async () => {
    assert.equal((await req('PUT', '/kv/empty', '')).status, 201);
    assert.equal(await (await req('GET', '/kv/empty')).text(), '');
    const big = new Uint8Array(MAX_VALUE_BYTES).fill(7);
    assert.equal((await req('PUT', '/kv/big', big)).status, 201);
    assert.equal((await (await req('GET', '/kv/big')).arrayBuffer()).byteLength, MAX_VALUE_BYTES);
  });

  it('lists keys sorted', async () => {
    await req('PUT', '/kv/Z', '1');
    await req('PUT', '/kv/a', '1');
    const res = await req('GET', '/kv');
    assert.match(res.headers.get('content-type') ?? '', /application\/json/);
    const keys = (await res.json()) as string[];
    assert.deepEqual(keys, [...keys].sort());
    assert.equal((await req('DELETE', '/kv')).status, 405);
  });

  it('errors', async () => {
    for (const p of ['/kv/', '/kv/a.b', '/kv/a/b', `/kv/${'x'.repeat(65)}`, '/kv/%41'])
      assert.equal((await req('GET', p)).status, 400, p);
    assert.equal((await req('GET', `/kv/${'x'.repeat(64)}`)).status, 404);
    assert.equal((await req('GET', '/nope')).status, 404);
    assert.equal((await req('GET', '/health/')).status, 404);
    assert.equal((await req('PATCH', '/kv/a')).status, 405);
  });
});
